# ---------------------------------------------------------------------------------------------------------------------
# MODULE PARAMETERS
# These variables are expected to be passed in by the operator when calling this terraform module.
# ---------------------------------------------------------------------------------------------------------------------

# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------

variable "vpc_id" {
  description = "The VPC Id for the resources to be created in"
  type        = string
}

variable "subnet_ids" {
  description = "Subnet IDs to put this DB instance in"
  type        = list(string)
}

variable "env" {
  description = "The standard name for the running environment.  One of: dev, staging, prod"
  type        = string
}

variable "pg_version" {
  description = "Postgres database version prefix"
  type        = string
  # default     = "11.6"
}

variable "name" {
  description = "The name to use for the resources created"
  type        = string
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "db_name" {
  description = "Database name to create when creating the DB instance"
  type        = string
  default     = ""
}

variable "admin_username" {
  description = "Username for the initial database user"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to assign to the compute resources"
  type        = map(any)
  default     = {}
}

variable "subnet_group_name_override" {
  description = "Optional override for subnet group name. Can be used when moving DB Subnet Groups."
  type        = string
  default     = ""
}

variable "security_group_ids" {
  description = "An optional list of VPC security groups to attach to the DB instance.  These are in additional to the default security created."
  type        = list(string)
  default     = []
}

variable "allocated_storage" {
  description = "The initial storage allocated in gibibytes"
  type        = number
  default     = 100
}
variable "final_snapshot" {
  description = "Take a snapshot before tearing down this db instance"
  type        = bool
  default     = true
}
variable "trusted_cidr_blocks" {
  description = "A optional list of CIDR blocks to allow access to the DB."
  type        = list(string)
  default     = []
}
variable "port" {
  description = "The port on which the DB accepts connections."
  type        = number
  default     = 5432
}
variable "trusted_security_group_ids" {
  description = "A optional list of security groups to allow access to the DB."
  type        = list(string)
  default     = []
}

variable "backup_window" {
  description = "Window for DB to run database backups"
  type        = string
  default     = "19:15-20:15"
}

variable "backup_retention_period" {
  description = "The days to retain backups for. Must be between 0 and 35."
  type        = number
  default     = 21
}

variable "replica_retention_period" {
  description = "The retention period for backup replication in days. Must be between 0 and 35."
  type        = number
  default     = 21
}

variable "deletion_protection" {
  description = "When true, the DB instance cannot be deleted via the API util the flag is disabled"
  type        = bool
  default     = true
}

variable "cloudwatch_logs_exports" {
  description = "List of log types to enable for exporting to CloudWatch logs"
  type        = list(string)
  default     = ["upgrade"]
}

variable "name_prefix" {
  description = "An optional string that will be pre-pended to the beginning of the resource names or paths"
  type        = string
  default     = ""
}

variable "name_suffix" {
  description = "An optional string that will be appended to the end of the resource names"
  type        = string
  default     = ""
}

variable "iam_database_authentication_enabled" {
  description = "Enable IAM auth"
  type        = bool
  default     = true
}

variable "instance_class" {
  description = "DB instance class"
  type        = string
  default     = "db.m5.large"
}

variable "storage_encrypted" {
  description = "Specifies whether the DB instance is encrypted"
  type        = bool
  default     = true
}

variable "storage_type" {
  description = "Type of storage used for backend"
  type        = string
  default     = "gp2"
}

variable "iops" {
  description = "IOPS setting for gp3 volumes, only used when allocated_storage >= 400"
  type        = number
  default     = 12000
}

variable "storage_throughput" {
  description = "Throughput setting for gp3 volumes, only used when allocated_storage >= 400"
  type        = number
  default     = 500
}

variable "kms_key_arn" {
  description = "KMS Key ARN to be used for database encryption."
  type        = string
  default     = ""
}
variable "kms_key_id" {
  description = "KMS Key ID to be used for database encryption."
  type        = string
  default     = ""
}
variable "kms_replication_key_arn" {
  description = "KMS Key ARN to be used for database encryption of the replicated cross region backups"
  type        = string
  default     = ""
}
variable "kms_replication_key_id" {
  description = "KMS Key ID to be used for database encryption of the replicated cross region backups"
  type        = string
  default     = ""
}
variable "encrypt_replicas" {
  description = "Should backup replicas be encrypted?"
  type        = bool
  default     = true
}

variable "ca_cert_identifier" {
  description = "RDS CA cert identifier to use"
  type        = string
  default     = "rds-ca-rsa2048-g1"
}

variable "security_group_name_override" {
  description = "Optional override for local access sg name. Can be used when moving DB Subnet Groups."
  type        = string
  default     = ""
}

variable "dba_security_group_name_override" {
  description = "Optional override for external access SG name. Can be used when moving DB Subnet Groups."
  type        = string
  default     = ""
}
variable "maintenance_window" {
  description = "DB database automatic maintenance / upgrades window"
  type        = string
  default     = "Sat:05:00-Sat:07:00"
}

variable "enhanced_monitoring_enabled" {
  description = "Creates IAM Role and enables Enhanced Monitoring on DB"
  type        = bool
  default     = false
}

variable "performance_insights_enabled" {
  description = "Enables performance insights on DB"
  type        = bool
  default     = false
}

variable "max_allocated_storage" {
  description = "When configured, the upper limit to which Amazon DB can automatically scale the storage of the DB instance.  Set to 0 to turn off"
  type        = number
  default     = 1000
}

variable "multi_az" {
  description = "Specifies if the DB instance is multi-AZ"
  type        = bool
  default     = true
}

variable "parameters" {
  description = "A map of DB parameters to apply via a parameter group.  If map is empty, the default parameter group will be used"
  type        = set(map(string))
  default     = []
}

variable "snapshot_identifier" {
  description = "Optional identifier for a snapshot to be restored from. Leave blank to create a fresh DB instance"
  type        = string
  default     = null
}

variable "create_before_destroy" {
  description = "Optional value to indicate whether the paramater group should be create and then deleted"
  type        = bool
  default     = true
}

