# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# SET UP A REDIS INSTANCE/CLUSTER FOR GENERAL USE
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

# ---------------------------------------------------------------------------------------------------------------------
# SET TERRAFORM REQUIREMENTS FOR RUNNING THIS MODULE
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = "~> 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
    vault = {
      source  = "hashicorp/vault"
      version = "~> 3.0"
    }
  }
}

locals {
  kms_key_name           = var.name == "" ? "${var.region}/redis" : "${var.region}/${var.name}-redis"
  security_group_name    = var.name == "" ? "${var.region}-redis-sg" : "${var.region}-redis-${var.name}-sg"
  replication_group_name = var.name == "" ? "${var.region}-redis" : "${var.region}-redis-${var.name}"

  nonprod_instance_size = "cache.t4g.small"
  prod_instance_size    = "cache.m6g.large"

  service_user_namespaces = {
    for k, v in var.service_users :
    k => v.namespaces != null ? v.namespaces : [{ name = k, separator = "-" }]
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# CREATE THE REDIS KMS KEY
# ----------------------------------------------------------------------------------------------------------------------

module "redis_cmk" {
  source  = "crow.infrastructure.immuta.io/internal/security-kms-key/aws"
  version = "v3.0.0"

  customer_master_keys = {
    (local.kms_key_name) = {
      allow_manage_key_permissions_with_iam = true
      enable_key_rotation                   = true
      tags                                  = var.tags
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# CREATE THE REDIS SECURITY GROUP
# ----------------------------------------------------------------------------------------------------------------------

module "redis_sg" {
  source  = "crow.infrastructure.immuta.io/internal/networking-security-group/aws"
  version = "v3.0.0"

  vpc_id                     = var.vpc_id
  security_group_name        = local.security_group_name
  security_group_description = "The security group used to control access to the Hosting Redis cluster"

  security_group_rules_cidr = {
    redis = {
      description = "Redis Access"
      type        = "ingress"
      from_port   = var.port
      to_port     = var.port
      protocol    = "tcp"
      cidr_blocks = var.allowed_cidr_blocks
    },
    egress = {
      description = "default egress rule"
      type        = "egress"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# CREATE THE USER GROUP AND DEFAULT USER
# ----------------------------------------------------------------------------------------------------------------------

resource "random_password" "service" {
  for_each = var.service_users

  length           = 64
  lower            = true
  min_lower        = 4
  min_numeric      = 4
  min_special      = 4
  min_upper        = 4
  numeric          = true
  override_special = "!&#$^-"
  special          = true
  upper            = true
}

resource "vault_generic_secret" "service" {
  for_each = var.service_users

  path = "secret/platform/${var.env}/elasticache/${var.region}/${local.replication_group_name}/${each.value.vault_secret_name != null ? each.value.vault_secret_name : each.key}"

  data_json = <<EOT
{
  "user_name": "${each.key}",
  "password":  "${random_password.service[each.key].result}"
}
EOT
}

resource "aws_elasticache_user" "service" {
  for_each = var.service_users

  user_id   = each.key
  user_name = each.key
  access_string = format(
    "on %s -@all %s",
    join(" ", [for ns in local.service_user_namespaces[each.key] : "~${ns.name}${ns.separator}*"]),
    each.value.acl,
  )
  engine    = "REDIS"
  passwords = [random_password.service[each.key].result]
}

resource "aws_elasticache_user_group" "default" {
  engine        = "REDIS"
  user_group_id = var.name == "" ? "${var.region}-redis-ug" : "${var.region}-redis-${var.name}-ug"
  user_ids      = ["default"]

  lifecycle {
    ignore_changes = [user_ids]
  }
}

resource "aws_elasticache_user_group_association" "service" {
  for_each = var.service_users

  user_group_id = aws_elasticache_user_group.default.user_group_id
  user_id       = aws_elasticache_user.service[each.key].user_id
}

# ----------------------------------------------------------------------------------------------------------------------
# CREATE THE REDIS CLUSTER
# ----------------------------------------------------------------------------------------------------------------------
module "redis_cluster" {
  source  = "crow.infrastructure.immuta.io/internal/data-elasticache-redis/aws"
  version = "v2.0.0"

  name          = local.replication_group_name
  redis_version = "6.x"

  # if var.instance_size override is set then use that, otherwise use prod or nonprod default depending on is_prod status
  instance_type = (
    var.instance_size != "" ? var.instance_size : (
      var.is_prod ? local.prod_instance_size : local.nonprod_instance_size
    )
  )

  subnet_ids = var.subnet_ids
  security_group_ids = [
    module.redis_sg.security_group_id
  ]

  user_group_ids = [aws_elasticache_user_group.default.id]

  replication_group_size    = var.is_prod ? 2 : 1
  enable_automatic_failover = var.is_prod
  enable_multi_az           = var.is_prod

  kms_key_id = module.redis_cmk.key_arns[local.kms_key_name]

  snapshot_retention_limit = var.is_prod ? 3 : 0
  snapshot_window          = var.is_prod ? "04:00-05:00" : ""
  apply_immediately        = var.is_prod ? false : true
  maintenance_window       = "sat:05:00-sat:06:00"

  port = var.port

  tags = var.tags
}

