/**
 * # Postgres Create Users
 * ## Module Name: postgres-create-users
 * ## This module is to be used to create multiple (or single) users in a postgres db WITHOUT any grants or roles attached
 */

# ---------------------------------------------------------------------------------------------------------------------
# SET TERRAFORM REQUIREMENTS FOR RUNNING THIS MODULE
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = "~> 1.0"

  required_providers {
    postgresql = {
      source  = "cyrilgdn/postgresql"
      version = "~> 1.0"
    }
    random = {
      version = "~> 3.0"
    }
    vault = {
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CREATE A TERRAFORM RESOURCE
# ---------------------------------------------------------------------------------------------------------------------
resource "postgresql_role" "database_user" {
  for_each = var.users

  name        = each.key
  password    = random_password.db_password[each.key].result
  login       = true
  create_role = false

  lifecycle {
    ignore_changes = [
      roles
    ]
  }

  depends_on = [random_password.db_password]
}

resource "random_password" "db_password" {
  for_each = var.users

  length      = var.password_settings.length
  lower       = var.password_settings.lowercase
  min_lower   = var.password_settings.min_lower
  min_numeric = var.password_settings.min_numeric
  min_special = var.password_settings.min_special
  min_upper   = var.password_settings.min_upper
  numeric          = var.password_settings.numeric
  override_special = var.password_settings.override_special
  special          = var.password_settings.special
  upper            = var.password_settings.upper

  lifecycle {
    ignore_changes = [
      length,
      lower,
      min_lower,
      min_numeric,
      min_special,
      min_upper,
      override_special,
      special,
      upper
    ]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# STORE DB CREDENTIALS IN VAULT
# ---------------------------------------------------------------------------------------------------------------------
resource "vault_kv_secret_v2" "db_users" {
  depends_on = [postgresql_role.database_user]

  for_each = {
    for user, val in var.users : user => val
    if val.vault
  }

  mount               = var.vault_mount
  name                = each.value.vault_path
  cas                 = 1
  delete_all_versions = false
  data_json = jsonencode(
    {
      user = each.key
      pass = random_password.db_password[each.key].result
    }
  )
  custom_metadata {
    data = {
      tags = jsonencode(var.tags)
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# MODULE PARAMETERS
# These variables are expected to be passed in by the operator when calling this terraform module.
# ---------------------------------------------------------------------------------------------------------------------


# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------

variable "database_name" {
  description = "Name of the database to be created, will also be used as the prefix for user creation unless the user name override variables are set."
  type        = string
}

variable "vault_path" {
  description = "The vault path that the db_user secrets will be created in"
  type        = string
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "create_database" {
  description = "Create the database"
  type        = bool
  default     = true
}

variable "schema_names" {
  description = "Schema to add and create where to add user privileges"
  type        = list(string)
  default     = ["public"]
}

variable "password_settings" {
  description = "Password settings to use when generating random passwords for ALL users created by this module"
  type = object({
    length           = number
    lowercase        = bool
    min_lower        = number
    min_numeric      = number
    min_special      = number
    min_upper        = number
    numeric          = bool
    override_special = string
    special          = bool
    upper            = bool
  })

  default = ({
    length           = 64
    lowercase        = true
    min_lower        = 4
    min_numeric      = 4
    min_special      = 4
    min_upper        = 4
    numeric          = true
    override_special = "-_"
    special          = true
    upper            = true
  })
}

variable "admin_name_override" {
  description = "Admin name to use when creating the database (will be set as the database owner) instead of using the user_name_prefix"
  type        = string
  default     = ""
}

variable "user_name_override" {
  description = "User name to use when creating the database instead of the user_name_prefix"
  type        = string
  default     = ""
}

variable "admin_conn_limit" {
  description = "Connection limit for the admin role"
  type        = number
  default     = -1
}

variable "user_conn_limit" {
  description = "Connection limit for the user role"
  type        = number
  default     = -1
}

variable "admin_table_privs" {
  description = "Optional list of admin table privileges to assign to the admin user if it is being created"
  type        = list(string)
  default     = ["SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER"]
}

variable "admin_database_privs" {
  description = "Optional list of admin database privileges to assign to the admin user if it is being created"
  type        = list(string)
  default     = ["CREATE"]
}

variable "admin_exec_privs" {
  description = "Optional list of admin function/procdure privileges to assign to the admin user if it is being created"
  type        = list(string)
  default     = ["EXECUTE"]
}

variable "admin_create_role" {
  description = "Bool determing if the admin user should be granted CREATEROLE or not (default to false)"
  type = bool
  default = false
}

variable "user_privs" {
  description = "A list of string representing the privileges to give the user to the created database (SELECT, INSERT, etc..)"
  type        = list(string)
  default     = ["SELECT", "INSERT", "UPDATE", "DELETE"]
}

variable "db_encoding" {
  description = "Encoding to set at the database level"
  type        = string
  default     = "UTF8"
}

variable "vault_mount" {
  description = "mount point for vault engine"
  type        = string
  default     = "secret"
}

variable "create_vault_secret" {
  description = "toggle to create the vault secret"
  type        = bool
  default     = true
}

variable "admin_granted_roles" {
  description = "List of roles granted to the admin user"
  type        = list(string)
  default     = []
}

variable "user_granted_roles" {
  description = "List of roles granted to the standard user"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Map of key-value pairs to tag created resources with."
  type        = map(any)
  default     = {}
}
